import org.apache.commons.math3.util.ArithmeticUtils;

public class MCD {
  public static void main(String[] args) {
      int[] arr = {20, 8, 32, 36, 16};

      // El mismo patrón que LCM aplica. Reducción recursiva manual requerida:
      int mcd_actual = arr[0];
      for (int i = 1; i < arr.length; i++) {
          mcd_actual = ArithmeticUtils.gcd(mcd_actual, arr[i]);
      }

      System.out.println(mcd_actual);
  }
}
